const fs = require('fs');

const input = fs.readFileSync(0, 'utf8').trim().split('\n');
const n = parseInt(input[0], 10);
const s = input[1].trim();

let sfFlights = 0; // Seattle to San Francisco
let fsFlights = 0; // San Francisco to Seattle

for (let i = 0; i < n - 1; i++) {
    if (s[i] === 'S' && s[i + 1] === 'F') {
        sfFlights++;
    } else if (s[i] === 'F' && s[i + 1] === 'S') {
        fsFlights++;
    }
}

if (sfFlights > fsFlights) {
    console.log('YES');
} else {
    console.log('NO');
}

